const CLIENT_ID_ENV = 'CDS_LOGIN_CLIENT_ID';
const CLIENT_SECRET_ENV = 'CDS_LOGIN_CLIENT_SECRET';
const CLIENT_CERT_ENV = 'CDS_LOGIN_CLIENT_CERT';
const CLIENT_KEY_ENV = 'CDS_LOGIN_CLIENT_KEY';

function clientId(inlineId) {
    const clientid = inlineId ?? process.env[CLIENT_ID_ENV];
    if (!clientid) {
        throw `Client ID required: pass it as --client <id> or via the ${CLIENT_ID_ENV} environment variable.`;
    }
    return clientid;
}

function splitFirst(value, separator) {
    const i = value.indexOf(separator);
    return i === -1 ? [value, undefined] : [value.slice(0, i), value.slice(i + separator.length)];
}

/**
 * Resolve `--client` credentials, each part falling back to the environment
 * (`CDS_LOGIN_CLIENT_ID`/`CDS_LOGIN_CLIENT_SECRET`). Splits on the first colon only;
 * an empty client ID (`:secret`) is rejected.
 * @returns {{ clientid?: string, clientsecret?: string }}
 */
function clientCredentials(clientOption) {
    if (!clientOption) {
        return {};
    }
    const [id, secret] = typeof clientOption === 'string' ? splitFirst(clientOption, ':') : [];
    return { clientid: clientId(id), clientsecret: secret ?? process.env[CLIENT_SECRET_ENV] };
}

/**
 * Resolve `--mtls` credentials: client ID inline or from `CDS_LOGIN_CLIENT_ID`,
 * certificate and key only from `CDS_LOGIN_CLIENT_CERT`/`CDS_LOGIN_CLIENT_KEY`.
 * An inline `:key` is rejected.
 * @returns {{ clientid?: string, certificate?: string, key?: string }}
 */
function clientCertificate(mtlsOption) {
    if (!mtlsOption) {
        return {};
    }
    if (typeof mtlsOption === 'string' && mtlsOption.includes(':')) {
        throw `The client key cannot be passed on the command line. Pass only the client ID as --mtls <id>, and provide the certificate and key via the ${CLIENT_CERT_ENV} and ${CLIENT_KEY_ENV} environment variables.`;
    }
    const id = typeof mtlsOption === 'string' ? mtlsOption : undefined;
    const certificate = process.env[CLIENT_CERT_ENV];
    const key = process.env[CLIENT_KEY_ENV];
    if (!certificate || !key) {
        throw `Client certificate and key required: set the ${CLIENT_CERT_ENV} and ${CLIENT_KEY_ENV} environment variables.`;
    }
    return { clientid: clientId(id), certificate, key };
}

module.exports = {
    clientCredentials,
    clientCertificate,
    CLIENT_ID_ENV,
    CLIENT_SECRET_ENV,
    CLIENT_CERT_ENV,
    CLIENT_KEY_ENV
};
